/**
 * Compute pack score boosts from successful outcome patterns.
 * Returns a map of pack → keyword → boost amount.
 *
 * Rules:
 * - Only boost from completed runs with 0 corrections
 * - Never boost above +2 per keyword
 * - Never create new keywords — only boost existing ones
 *
 * @param {RunOutcome[]} outcomes
 * @returns {Record<string, number>} packName → boost amount
 */
export function computePackBoosts(outcomes) {
  const boosts = {};

  const cleanRuns = outcomes.filter(
    o => o.selectedPack && o.completionStatus === "completed" && o.corrections === 0
  );

  for (const o of cleanRuns) {
    const pack = o.selectedPack;
    boosts[pack] = Math.min((boosts[pack] || 0) + 0.5, 2.0);
  }

  return boosts;
}

def combine(verdicts: dict[str, dict[str, dict]], pair_ids: list[str], old_dropped: set) -> dict:
    """verdicts: judge -> pair_id -> parsed outcome. The kept ids (both judges keep), each judge's
    outcome counts, the 2x2 agreement table, and the comparison with the first check."""
    a, b = list(verdicts)
    table = {"both_keep": 0, f"only_{a}": 0, f"only_{b}": 0, "neither": 0}
    counts = {j: {} for j in verdicts}
    kept = []
    not_asked = {"outcome": "not asked (the other judge dropped it)"}
    for pid in pair_ids:
        va, vb = verdicts[a].get(pid, not_asked), verdicts[b].get(pid, not_asked)
        ka, kb = keeps(va), keeps(vb)
        for j, v in ((a, va), (b, vb)):
            o = v["outcome"]
            counts[j][o] = counts[j].get(o, 0) + 1
        key = "both_keep" if ka and kb else f"only_{a}" if ka else f"only_{b}" if kb else "neither"
        table[key] += 1
        if ka and kb:
            kept.append(pid)
    kept_set = set(kept)
    old_kept = set(pair_ids) - old_dropped
    return {
        "pairs": len(pair_ids),
        "kept": len(kept),
        "kept_ids": kept,
        "dropped_ids": [p for p in pair_ids if p not in kept_set],
        "judges_disagree": table[f"only_{a}"] + table[f"only_{b}"],
        "agreement": table,
        "outcomes": counts,
        "against_first_check": {
            "kept_by_both_checks": len(kept_set & old_kept),
            "kept_now_dropped_before": len(kept_set - old_kept),
            "dropped_now_kept_before": len(old_kept - kept_set),
            "dropped_by_both": len(set(pair_ids) - kept_set - old_kept),
        },
    }

/// A quote shorter than this, once normalised, proves nothing: a word like "the" is
/// found in almost any passage. Such a quote counts as not found.
pub const MIN_QUOTE_CHARS: usize = 12;

/// True when the normalised quote is at least [`MIN_QUOTE_CHARS`] long and sits inside
/// one evidence passage, normalised.
pub fn quote_found(quote: &str, evidence: &[Passage]) -> bool {
    let q = normalise(quote);
    q.chars().count() >= MIN_QUOTE_CHARS && evidence.iter().any(|p| normalise(&p.text).contains(&q))
}

/// Why `port` may not be the embed port, if it may not.
pub fn embed_port_conflict(port: u16, tunnel_port: u16) -> Option<&'static str> {
    let lanes_top = LANE_PORT_BASE + LANE_COUNT * LANE_PORT_STEP;
    let sidecar_top = SIDECAR_PORT_BASE + LANE_COUNT;
    match port {
        0..=1023 => Some("a privileged port"),
        LOCAL_OLLAMA_PORT => Some("the shared local Ollama's port"),
        p if p == tunnel_port || p == tunnel_port.saturating_add(1) => {
            Some("the configured tunnel's port or its runner port")
        }
        11435 | 11436 => Some("the plain lane's tunnel or runner port"),
        p if (LANE_PORT_BASE..lanes_top).contains(&p) => Some("a project lane's port range"),
        p if (SIDECAR_PORT_BASE..sidecar_top).contains(&p) => Some("the side-car port range"),
        _ => None,
    }
}

def edit_size(a: str, b: str) -> tuple[int, int]:
    """(characters changed, words changed): difflib, autojunk off, the larger side of each
    non-equal opcode, on characters and on whitespace-split words."""

    def changed(x, y):
        ops = difflib.SequenceMatcher(None, x, y, autojunk=False).get_opcodes()
        return sum(max(i2 - i1, j2 - j1) for op, i1, i2, j1, j2 in ops if op != "equal")

    return changed(a, b), changed(a.split(), b.split())

def span_logprob(token_logprobs: list[float], start: int, end: int) -> float:
    """Sum of log p(token i | tokens before i) for i in [start, end). token_logprobs[i] is token
    i's log-probability; token 0 has none and counts as 0."""
    return sum(token_logprobs[i] for i in range(max(start, 1), end))


def delta(
    strong_ids: list[int], strong_lp: list[float], flawed_ids: list[int], flawed_lp: list[float]
) -> float:
    """The secondary measure: the changed tokens only, between the common prefix and suffix."""
    prefix, end_s, end_f = changed_span(strong_ids, flawed_ids)
    return span_logprob(flawed_lp, prefix, end_f) - span_logprob(strong_lp, prefix, end_s)


def delta_tail(
    strong_ids: list[int],
    strong_lp: list[float],
    strong_end: int,
    flawed_ids: list[int],
    flawed_lp: list[float],
    flawed_end: int,
) -> float:
    """The primary measure (R&D's review): from the first changed token to the end of the answer,
    so the knock-on surprise after an edit counts. Each copy stops at its own answer end, before
    any trailing template tokens. The prefixes are identical, so this is the full-sequence
    difference."""
    prefix, _, _ = changed_span(strong_ids, flawed_ids)
    return span_logprob(flawed_lp, prefix, flawed_end) - span_logprob(strong_lp, prefix, strong_end)

def parse(response: dict) -> dict:
    """One judge's outcome: a verdict ("same", "changed", "unsure"), or "truncated" / "unparsed"."""
    message = response.get("message", {})
    out = {"thinking_chars": len(message.get("thinking") or ""), "done_reason": response.get("done_reason")}
    if response.get("done_reason") == "length":
        return out | {"outcome": "truncated"}
    data = extract_json_object(message.get("content") or "")
    if (
        not data
        or data.get("verdict") not in ("same", "changed", "unsure")
        or not isinstance(data.get("claim_changed"), bool)
    ):
        return out | {"outcome": "unparsed"}
    return out | {
        "outcome": data["verdict"],
        "claim_changed": data["claim_changed"],
        "reasoning": data.get("reasoning", ""),
    }

const RETRY_NUDGE: &str = "That reply did not follow the schema ({why}). Reply again with only the JSON object described, with keys reasoning, verdict, evidence_quote, evidence_source.";

/// Check one claim against its supplied context and the retrieved passages. A reply
/// that fails its schema is retried once; a second failure is an error, never a
/// verdict. A truncated reply or a server error is an error at once.
pub fn verify_one(
    chat: &dyn ChatBackend,
    cfg: &VerifyConfig,
    claim: &Claim,
    retrieved: &[Passage],
) -> Result<Verdict> {
    if claim.id.trim().is_empty() || claim.claim.trim().is_empty() {
        return Err(Error::Refused(
            "a claim needs an id and its text".to_string(),
        ));
    }
    let evidence = evidence_list(claim, retrieved);
    if evidence.is_empty() && claim.check_type != CheckType::Knowledge {
        return Err(Error::Refused(format!(
            "claim {} is a {} check with no evidence: supply context or retrieve passages",
            claim.id,
            claim.check_type.as_str()
        )));
    }
    let mut req = ChatRequest {
        model: cfg.model.clone(),
        messages: vec![
            Msg::new("system", card_text()),
            Msg::new("user", render_prompt(claim, &evidence)),
        ],
        format: cfg.structured.then(reply_schema),
        think: Some(cfg.think),
        temperature: Some(cfg.temperature),
        seed: Some(cfg.seed),
        num_ctx: Some(cfg.num_ctx),
        num_predict: Some(cfg.num_predict),
    };
    let mut timing = Timing::default();
    let mut last = String::new();
    for attempt in 1..=2 {
        let resp = chat.chat(&req)?;
        timing.attempts = attempt;
        timing.eval_count += resp.eval_count.unwrap_or(0);
        timing.prompt_eval_count += resp.prompt_eval_count.unwrap_or(0);
        timing.total_duration_ns += resp.total_duration.unwrap_or(0);
        match parse_reply(&resp.content) {
            Ok(reply) => return Ok(finish(cfg, claim, &evidence, reply, timing)),
            Err(why) => {
                req.messages.push(Msg::new("assistant", resp.content));
                req.messages
                    .push(Msg::new("user", RETRY_NUDGE.replace("{why}", &why)));
                last = why;
            }
        }
    }
    Err(Error::BadVerdict(format!(
        "claim {}: {last}, on both attempts",
        claim.id
    )))
}

